// The Zod mirror must accept exactly what Rust emits. These files are generated by
// crates/usage-model/tests/golden.rs, so a Rust-side shape change fails here until the schemas follow.
import { describe, expect, it } from 'vitest';
import errorCodes from '../../../contract/error-codes.json';
import ipc from '../../../contract/ipc.json';
import ipcCommands from '../../../contract/ipc-commands.json';
import settings from '../../../contract/settings.json';
import snapshot from '../../../contract/snapshot.json';
import {
  COMMANDS,
  defaultSettings,
  ERROR_CODES,
  EVENTS,
  ExternalLinkSchema,
  HARNESS_IDS,
  SecretKindSchema,
  SecretStatusSchema,
  SettingsSchema,
  SHIM_STATES,
  ShimStatusSchema,
  SnapshotSchema,
  VIEW_STATES,
} from '.';

describe('shared enumerations', () => {
  it('lists the same error codes, in the same order, as Rust', () => {
    expect([...ERROR_CODES]).toEqual(errorCodes);
  });

  it('registers exactly the commands and events the backend exposes', () => {
    expect(Object.values(COMMANDS).sort()).toEqual([...ipcCommands.commands].sort());
    expect(Object.values(EVENTS).sort()).toEqual([...ipcCommands.events].sort());
  });
});

describe('snapshot.json', () => {
  const parsed = SnapshotSchema.parse(snapshot);

  it('round-trips without losing a field', () => {
    expect(parsed).toEqual(snapshot);
  });

  it('keeps unknown percentages as null instead of coercing them to zero', () => {
    const unknown = parsed.views.flatMap((v) => v.windows).filter((w) => w.usedPct === null);
    expect(unknown.length).toBeGreaterThan(0);
  });

  it('covers every view state and every harness so the sample cannot lose coverage', () => {
    expect(new Set(parsed.views.map((v) => v.state))).toEqual(new Set(VIEW_STATES));
    expect(new Set(parsed.views.map((v) => v.id))).toEqual(new Set(HARNESS_IDS));
  });

  it('rejects a field the schema does not know (strictness canary)', () => {
    expect(SnapshotSchema.safeParse({ ...snapshot, extra: 1 }).success).toBe(false);
    const withExtraView = { ...snapshot, views: [{ ...snapshot.views[0], extra: 1 }] };
    expect(SnapshotSchema.safeParse(withExtraView).success).toBe(false);
  });
});

describe('settings.json', () => {
  it('parses every sample, including all three TLS modes', () => {
    const modes = Object.values(settings).map((s) => SettingsSchema.parse(s).litellm.tls.mode);
    expect(modes.sort()).toEqual(['custom_ca', 'insecure', 'system']);
  });

  it('keeps the TypeScript defaults identical to Settings::default()', () => {
    expect(defaultSettings).toEqual(settings.default);
  });

  it('rejects a secret-looking field the contract does not declare', () => {
    const tampered = { ...settings.default, litellm: { ...settings.default.litellm, apiKey: 'x' } };
    expect(SettingsSchema.safeParse(tampered).success).toBe(false);
  });
});

describe('ipc.json', () => {
  it('parses secret status, shim statuses and the link and secret enumerations', () => {
    expect(SecretStatusSchema.parse(ipc.secretStatus)).toEqual(ipc.secretStatus);
    for (const status of ipc.shimStatuses) expect(ShimStatusSchema.parse(status)).toEqual(status);
    expect(ipc.shimStates).toEqual([...SHIM_STATES]);
    expect(ipc.externalLinks).toEqual(ExternalLinkSchema.options);
    expect(ipc.secretKinds).toEqual(SecretKindSchema.options);
  });
});
